            if (trips.isNotEmpty()) {
                Result.Success(trips)
            } else {
                Result.Error(Exception("Empty"), "No upcoming trips")
            }

        } catch (e: Exception) {
            Result.Error(e, "Error fetching upcoming trips: ${e.message}")
        }
    }

    /**
     * Get trip by ID with full details
     */
    suspend fun getTripById(tripId: Long): Result<TripWithRouteAndBus> = 
        withContext(Dispatchers.IO) {
            try {
                val trip = tripDAO.getTripById(tripId)

                if (trip != null) {
                    Result.Success(trip)
                } else {
                    Result.Error(Exception("Not found"), "Trip not found")
                }

            } catch (e: Exception) {
                Result.Error(e, "Error fetching trip: ${e.message}")
            }
        }

    /**
     * Create new trip
     */
    suspend fun createTrip(
        routeId: Long,
        busId: Long,
        departureTime: Long,
        arrivalTime: Long,
        price: Double,
        tripDate: Long
    ): Result<Long> = withContext(Dispatchers.IO) {
        try {
            val trip = Trip(
                routeId = routeId,
                busId = busId,
                departureTime = departureTime,
                arrivalTime = arrivalTime,
                price = price,
                tripDate = tripDate,
                status = "SCHEDULED"
            )

            val id = tripDAO.insertTrip(trip)

            if (id > 0) {
                Result.Success(id)
            } else {
                Result.Error(Exception("Insert failed"), "Could not create trip")
            }

        } catch (e: Exception) {
            Result.Error(e, "Error creating trip: ${e.message}")
        }
    }

    /**
     * Cancel trip
     */
    suspend fun cancelTrip(tripId: Long): Result<Unit> = withContext(Dispatchers.IO) {
        try {
            tripDAO.cancelTrip(tripId)
            Result.Success(Unit)
        } catch (e: Exception) {
            Result.Error(e, "Error cancelling trip: ${e.message}")
        }
    }

    /**
     * Get all trips (for admin)
     */
    suspend fun getAllTrips(): Result<List<TripWithRouteAndBus>> = withContext(Dispatchers.IO) {
        try {
            val allTrips = tripDAO.getAllTrips().collect { trips ->
                if (trips.isNotEmpty()) {
                    return@withContext Result.Success(trips)
                } else {
                    return@withContext Result.Error(Exception("Empty"), "No trips found")
                }
            }
            // If collect completes without return
            Result.Error(Exception("Empty"), "No trips found")
        } catch (e: Exception) {
            Result.Error(e, "Error fetching all trips: ${e.message}")
        }
    }
}

package com.example.busbooking.data.dao

import androidx.lifecycle.LiveData
import androidx.room.*
import com.example.busbooking.data.entity.User
import kotlinx.coroutines.flow.Flow

/**
 * UserDAO - Complete user management queries
 *
 * Supports:
 * - Registration: Insert with email uniqueness check
 * - Authentication: Login by email
 * - Profile: Get/update user info
 * - Admin: List users, change roles, search, block/unblock
 *
 * Conflict Strategy: IGNORE on insert (email unique at DB level)
 */
@Dao
interface UserDAO {

    // ========================================================================
    // REGISTRATION & AUTHENTICATION
    // ========================================================================

    /**
     * Register new user
     * Conflict: IGNORE if email exists (unique constraint at DB level)
     * Return: rowId if success, 0 if conflict
     */
    @Insert(onConflict = OnConflictStrategy.IGNORE)
    suspend fun registerUser(user: User): Long

    /**
     * Check if email already registered
     */
    @Query("SELECT EXISTS(SELECT 1 FROM users WHERE email = :email)")
    suspend fun emailExists(email: String): Boolean

    /**
     * Login: Get user by email
     */
    @Query("SELECT * FROM users WHERE email = :email LIMIT 1")
    suspend fun getUserByEmail(email: String): User?

    /**
     * Update user password (hashed)
     */
    @Query("UPDATE users SET password = :hashedPassword WHERE id = :userId")
    suspend fun updatePassword(userId: Long, hashedPassword: String)

    // ========================================================================
    // USER PROFILE
    // ========================================================================

    /**
     * Get user by ID (LiveData for reactive binding)
     */
    @Query("SELECT * FROM users WHERE id = :userId")
    fun getUserById(userId: Long): LiveData<User>

    /**
     * Get user by ID (suspend for immediate access)
     */
    @Query("SELECT * FROM users WHERE id = :userId")
    suspend fun getUserByIdSuspend(userId: Long): User?

    /**
     * Update user profile
     */
    @Update
    suspend fun updateUser(user: User)

    /**
     * Soft delete: Block user account
     */
    @Query("UPDATE users SET isBlocked = 1 WHERE id = :userId")
    suspend fun blockUser(userId: Long)

    /**
     * Unblock user account
     */
    @Query("UPDATE users SET isBlocked = 0 WHERE id = :userId")
    suspend fun unblockUser(userId: Long)

    // ========================================================================
    // ADMIN: USER MANAGEMENT
    // ========================================================================

    /**
     * Get all active users (paginated)
     */
    @Query("""
        SELECT * FROM users 
        WHERE isBlocked = 0 
        ORDER BY createdAt DESC 
        LIMIT :limit OFFSET :offset
    """)
    fun getAllUsers(limit: Int, offset: Int): Flow<List<User>>

    /**
     * Get users by role
     */
    @Query("SELECT * FROM users WHERE role = :role AND isBlocked = 0 ORDER BY createdAt DESC")
    fun getUsersByRole(role: String): Flow<List<User>>

    /**
     * Search users by name or email
     */
    @Query("""
        SELECT * FROM users 
        WHERE (name LIKE '%' || :searchQuery || '%' 
           OR email LIKE '%' || :searchQuery || '%')
          AND isBlocked = 0
        ORDER BY createdAt DESC
    """)
    fun searchUsers(searchQuery: String): Flow<List<User>>

    /**
     * Change user role
     */
    @Query("UPDATE users SET role = :newRole WHERE id = :userId")
    suspend fun changeUserRole(userId: Long, newRole: String)

    /**
     * Hard delete user and all cascaded data
     */
    @Query("DELETE FROM users WHERE id = :userId")
    suspend fun deleteUser(userId: Long)

    /**
     * Get total user count
     */
    @Query("SELECT COUNT(*) FROM users WHERE isBlocked = 0")
    suspend fun getUserCount(): Long

    /**
     * Get user count by role
     */
    @Query("SELECT COUNT(*) FROM users WHERE role = :role AND isBlocked = 0")
    suspend fun getUserCountByRole(role: String): Long
}

